func deriveKey(key []byte) ([]byte, error) {
    // Use HKDF to derive a key with sufficient entropy
    h := hmac.New(sha256.New, nil)
    _, err := h.Write([]byte("AES-256-GCM Key"))
    if err != nil {
        return nil, fmt.Errorf("failed to write salt: %v", err)
    }
    derivedKey := make([]byte, 32)
    rand.Read(derivedKey) // Use a secure random source
    return derivedKey, nil
}

func encryptData(key []byte, data []byte) ([]byte, []byte, []byte, error) {
    aesKey, err := deriveKey(key)
    if err != nil {
        return nil, nil, nil, fmt.Errorf("failed to derive key: %v", err)
    }

    block, err := aes.NewCipher(aesKey)
    if err != nil {
        return nil, nil, nil, fmt.Errorf("failed to create AES cipher: %v", err)
    }

    iv := make([]byte, block.BlockSize())
    if _, err := rand.Read(iv); err != nil {
        return nil, nil, nil, fmt.Errorf("failed to generate IV: %v", err)
    }

    aesgcm, err := cipher.NewGCM(block)
    if err != nil {
        return nil, nil, nil, fmt.Errorf("failed to create GCM: %v", err)
    }

    encryptedData := aesgcm.Seal(nil, iv, data, nil)

    return encryptedData, iv, aesKey, nil
}

