	key := make([]byte, 64) // Example key of sufficient length
	rand.Read(key)         // Fill with random bytes

	plaintext := []byte("Sensitive Data")

	encrypted, iv, usedKey := encryptData(key, plaintext)

	// Verify by decrypting
	block, err := aes.NewCipher(usedKey)
	if err != nil {
		panic(err)
	}

	decrypter := cipher.NewCBCDecrypter(block, iv)
	decrypted := make([]byte, len(encrypted))
	decrypter.CryptBlocks(decrypted, encrypted)

